const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const ws = wb.Sheets['Products'];
const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

// Add new headers for the additional fields if not present
const newHeaders = [
  'Product ID', 'Name', 'Category', 'Price', 'In Stock',
  'Subcategory', 'Brand', 'Stock Quantity', 'Rating', 'Review Count',
  'Description', 'Compatibility', 'Variants', 'Shipping Days',
  'Gift Wrap Available', 'Backorder Available', 'Warranty (Months)',
  'Return Window (Days)', 'Restocking Fee (%)', 'Weight (lbs)', 'Is Fragile'
];

// Update header row
data[0] = newHeaders;

// Pad existing rows to match new header length
for (let i = 1; i < data.length; i++) {
  while (data[i].length < newHeaders.length) {
    data[i].push('');
  }
}

// Add PROD-2028EE row with full details
const newRow = [
  'PROD-2028EE',                          // Product ID
  'Magnetic Wireless Charging Stand',     // Name
  'electronics',                          // Category
  45,                                     // Price
  'Yes',                                  // In Stock
  'Mobile Accessories',                   // Subcategory
  'VoltForge',                            // Brand
  96,                                     // Stock Quantity
  3.9,                                    // Rating
  459,                                    // Review Count
  'New magnetic wireless charging stand in black for Qi-enabled phones with up to 15W charging. Physical goods accessory with taxable retail pricing and inventory tracking enabled.',  // Description
  'Qi-enabled devices (including iPhone 15)',  // Compatibility
  'None',                                 // Variants
  3,                                      // Shipping Days
  'Yes',                                  // Gift Wrap Available
  'No',                                   // Backorder Available
  12,                                     // Warranty (Months)
  30,                                     // Return Window (Days)
  0,                                      // Restocking Fee (%)
  0.0,                                    // Weight (lbs)
  'No'                                    // Is Fragile
];
data.push(newRow);

// Write back
const newWs = XLSX.utils.aoa_to_sheet(data);
wb.Sheets['Products'] = newWs;
XLSX.writeFile(wb, '/workspace/testbed/data/product_inventory.xlsx');
console.log('File updated successfully.');
"

